// Data layer: Tauri commands in the app, static JSON (generated by the Rust `export-mock`
// tool from simulated data) in a plain browser preview. The UI never does money arithmetic;
// it only divides by 1e9 to display values that Rust already computed.

export type PeriodKind = "today" | "week" | "month" | "year";
export type PowerStateName = "active" | "idle" | "sleep" | "hibernate" | "off";

export interface Amount {
  seconds: number;
  kwh_nano: number;
  cost_nano: number;
  cost_minor: number;
}
export interface StateRow { state: PowerStateName; amount: Amount }
export interface PeriodRow { id: string; label: string; amount: Amount }
export interface Point {
  start: string;
  local_start: string;
  future: boolean;
  by_state: StateRow[];
  total: Amount;
}
export interface Warning { code: string; message: string }
export interface Current {
  state: PowerStateName;
  watts: string;
  low: string;
  high: string;
  layer: "sensors" | "calibrated" | "default";
  method: string;
  on_ac: boolean | null;
}
export interface Dashboard {
  period: PeriodKind;
  from: string;
  to: string;
  currency: string;
  minor_digits: number;
  tariff_name: string;
  total: Amount;
  by_state: StateRow[];
  by_period: PeriodRow[];
  bucket: "hour" | "day" | "month";
  timeline: Point[];
  confidence: { measured_sensors_permille: number; calibrated_permille: number; default_model_permille: number };
  warnings: Warning[];
  current: Current | null;
  fixed_fees: { cost_nano: number; cost_minor: number } | null;
  grand_total_minor: number;
  /** 0 = the current period, -1 = the one before, ... */
  offset: number;
  /** "YYYY-MM-DD" local dates of the first and last day of the period. */
  period_start: string;
  period_end_inclusive: string;
  has_earlier: boolean;
}
export interface Scenario {
  current_cost_nano: number;
  new_cost_nano: number;
  saving_nano: number;
  saving_per_year_nano: number;
  kwh_saved_nano: number;
  hours_affected: number;
}
export interface WhatIfParams {
  night_start_hour: number;
  night_end_hour: number;
  off_watts: string;
  shift_percent: number;
}
export interface WhatIf {
  shutdown_at_night: Scenario;
  shift_to_cheap_period: Scenario;
  cheapest_period: string;
  params: WhatIfParams;
  note: string;
}
export interface AppInfo {
  simulated: boolean;
  preview: boolean;
  version: string;
  tracker_running: boolean;
  sensor_issues: string[];
  /** e.g. "M8 01fbf4a": which commit this build came from. */
  build?: string;
  data_dir?: string;
  tariff_note?: string | null;
  autostart_enabled?: boolean;
}

export type UpdateStatus =
  | { state: "unknown" }
  | { state: "unavailable"; reason: string }
  | { state: "up_to_date" }
  | { state: "available"; hash: string; subject: string };

export type Theme = "system" | "light" | "dark";
export interface CalibrationPoint { util_permille: number; watts: string }
export interface EstimatorCfg {
  psu_efficiency: string;
  baseline_w: string;
  per_drive_w: string;
  include_monitor: boolean;
  monitor_w: string;
  sleep_w: string;
  hibernate_w: string;
  off_standby_w: string;
  unplugged_when_off: boolean;
  prefer_calibrated: boolean;
  hardware: { cpu_tdp_w: string; cpu_idle_w: string; gpu_tdp_w: string | null; gpu_idle_w: string; drives: number };
  calibration: { points: CalibrationPoint[] } | null;
}
export interface Settings {
  first_run_done: boolean;
  region: { country: string | null; confirmed: boolean; ip_lookup_opt_in: boolean };
  tariff_id: string;
  estimator: EstimatorCfg;
  thresholds: {
    input_idle_secs: number;
    cpu_enter_percent: number;
    cpu_exit_percent: number;
    gpu_enter_percent: number;
    gpu_exit_percent: number;
    exit_debounce_ticks: number;
  };
  gap_assumptions: { crash: PowerStateName; unknown: PowerStateName };
  budget: { monthly_minor: number; alert_percents: number[] } | null;
  include_fixed_fees: boolean;
  autostart: boolean;
  theme: Theme;
  detail_retention_days: number;
}
export interface PresetInfo {
  id: string;
  version: number;
  name: string;
  country: string;
  distributor: string | null;
  currency: string;
  verification: "verified" | "partial" | "unverified" | "example" | null;
  valid_from: string;
  valid_to: string | null;
  source: "bundled" | "user";
}
export interface TariffList { presets: PresetInfo[]; problems: string[]; selected_id: string; user_dir: string }
export interface ValidationReport {
  ok: boolean;
  errors: string[];
  warnings: Warning[];
  prices: { period_id: string; label: string; excl_vat: string; gross: string }[];
}
export interface SaveTariffResult { info: PresetInfo; recomputed_spans: number | null; clipped_by_compaction: boolean }
export interface RegionInfo { candidates: { country: string; source: "timezone" | "locale" }[]; suggestions: PresetInfo[] }
export interface Reestimate { spans: number; clipped_by_compaction: boolean }
export interface StateLine { state: PowerStateName; seconds: number; kwh_nano: number; cost_nano: number }
export interface PeriodLine { id: string; label: string; seconds: number; kwh_nano: number; cost_nano: number }
export interface Measurement {
  start: string;
  end: string;
  seconds: number;
  kwh_nano: number;
  cost_nano: number;
  cost_minor: number;
  currency: string;
  minor_digits: number;
  avg_watts: string;
  by_state: StateLine[];
  by_period: PeriodLine[];
  estimated_tail_seconds: number;
  untracked_seconds: number;
  measured_sensors_permille: number;
  calibrated_permille: number;
  default_model_permille: number;
  tariff_name: string;
}
export interface StopwatchSession { id: string; label: string; result: Measurement }
export interface StopwatchStatus { running: { start: string; label: string } | null; live: Measurement | null; now: string }
export interface ExportRequest {
  path: string;
  format: "csv" | "json";
  granularity: "hour" | "day";
  fromDate: string;
  toDate: string;
}

const inTauri = typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;

async function invoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  const { invoke } = await import("@tauri-apps/api/core");
  return invoke<T>(cmd, args);
}

async function mock<T>(file: string): Promise<T> {
  const res = await fetch(`${import.meta.env.BASE_URL}mock/${file}`);
  if (!res.ok) throw new Error(`mock ${file}: ${res.status}`);
  return res.json();
}

/** Tauri rejects with a string or, for validation failures, an array of strings. */
export function errorLines(e: unknown): string[] {
  if (Array.isArray(e)) return e.map(String);
  if (e instanceof Error) return [e.message];
  return [String(e)];
}

const PREVIEW_SETTINGS_KEY = "pc-preview-settings";

function previewDefaults(): Settings {
  return {
    first_run_done: false,
    region: { country: null, confirmed: false, ip_lookup_opt_in: false },
    tariff_id: "bg-electrohold",
    estimator: {
      psu_efficiency: "0.85", baseline_w: "20", per_drive_w: "2.5", include_monitor: false, monitor_w: "25", sleep_w: "1",
      hibernate_w: "0", off_standby_w: "1", unplugged_when_off: false, prefer_calibrated: true,
      hardware: { cpu_tdp_w: "65", cpu_idle_w: "5", gpu_tdp_w: null, gpu_idle_w: "0", drives: 1 },
      calibration: null,
    },
    thresholds: { input_idle_secs: 120, cpu_enter_percent: 20, cpu_exit_percent: 10, gpu_enter_percent: 25, gpu_exit_percent: 10, exit_debounce_ticks: 3 },
    gap_assumptions: { crash: "off", unknown: "off" },
    budget: null,
    include_fixed_fees: false,
    autostart: false,
    theme: "system",
    detail_retention_days: 90,
  };
}

function previewLoad(): Settings {
  try {
    const raw = localStorage.getItem(PREVIEW_SETTINGS_KEY);
    return raw ? { ...previewDefaults(), ...JSON.parse(raw) } : previewDefaults();
  } catch {
    return previewDefaults();
  }
}

/**
 * Browser-preview stopwatch: a fixed pretend 45 W draw at the Electrohold daytime price, kept in
 * localStorage, so the screen can be tried without the app. Integer maths only; the real numbers
 * come from the Rust backend.
 */
const SW_RUN = "pc-preview-sw-run";
const SW_HIST = "pc-preview-sw-hist";
const previewJson = <T,>(key: string, fallback: T): T => {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
};
const previewSet = (key: string, value: unknown) => {
  try {
    if (value === null) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify(value));
  } catch {
    /* preview only */
  }
};
function previewMeasure(startIso: string, end: Date): Measurement {
  const seconds = Math.max(0, Math.round((end.getTime() - new Date(startIso).getTime()) / 1000));
  const kwh_nano = Math.round((45 * seconds * 10000) / 36); // 45 W * s / 3.6e6 kWh, in nano
  const cost_nano = Math.round((kwh_nano * 154248) / 1_000_000);
  return {
    start: startIso, end: end.toISOString(), seconds, kwh_nano, cost_nano, cost_minor: Math.round(cost_nano / 1e7), currency: "EUR", minor_digits: 2,
    avg_watts: seconds > 0 ? "45.0" : "0.0",
    by_state: seconds > 0 ? [{ state: "active", seconds, kwh_nano, cost_nano }] : [],
    by_period: seconds > 0 ? [{ id: "day", label: "Day", seconds, kwh_nano, cost_nano }] : [],
    estimated_tail_seconds: 0, untracked_seconds: 0, measured_sensors_permille: 0, calibrated_permille: 0, default_model_permille: seconds > 0 ? 1000 : 0,
    tariff_name: "Preview tariff",
  };
}
const previewStopwatch = {
  start(label: string) {
    previewSet(SW_RUN, { start: new Date().toISOString(), label: label.trim() });
  },
  status(): StopwatchStatus {
    const running = previewJson<{ start: string; label: string } | null>(SW_RUN, null);
    const now = new Date();
    return { running, live: running ? previewMeasure(running.start, now) : null, now: now.toISOString() };
  },
  stop(): StopwatchSession {
    const running = previewJson<{ start: string; label: string } | null>(SW_RUN, null);
    if (!running) throw ["the stopwatch is not running"];
    const session = { id: String(new Date(running.start).getTime()), label: running.label, result: previewMeasure(running.start, new Date()) };
    previewSet(SW_HIST, [session, ...previewJson<StopwatchSession[]>(SW_HIST, [])].slice(0, 50));
    previewSet(SW_RUN, null);
    return session;
  },
  cancel() {
    previewSet(SW_RUN, null);
  },
  history: (): StopwatchSession[] => previewJson<StopwatchSession[]>(SW_HIST, []),
  remove(id: string) {
    previewSet(SW_HIST, previewJson<StopwatchSession[]>(SW_HIST, []).filter((s) => s.id !== id));
  },
};

const PREVIEW_ONLY = ["This is the browser preview: saving, validation and exports run inside the PowerCost app."];

export const api = {
  /** `offset` 0 is the current period, -1 the one before, and so on. */
  dashboard: (period: PeriodKind, offset = 0): Promise<Dashboard> =>
    inTauri ? invoke("get_dashboard", { period, offset }) : mock(offset === 0 ? `dashboard-${period}.json` : `dashboard-${period}-${-offset}.json`),

  whatIf: (params: WhatIfParams, days: number): Promise<WhatIf> => {
    if (inTauri) return invoke("get_what_if", { params, days });
    const steps = [0, 25, 50, 75, 100];
    const nearest = steps.reduce((a, b) => (Math.abs(b - params.shift_percent) < Math.abs(a - params.shift_percent) ? b : a));
    return mock(`whatif-${nearest}.json`);
  },

  info: async (): Promise<AppInfo> =>
    inTauri
      ? invoke("get_app_info")
      : { simulated: true, preview: true, version: "preview", tracker_running: false, sensor_issues: [] },

  /** The last (cached) update check. Local only: compares this build with the project folder. */
  updateStatus: async (): Promise<UpdateStatus> => (inTauri ? invoke("get_update_status") : { state: "unavailable", reason: "updates only work inside the PowerCost app" }),
  /** Check the project folder for a newer commit now. */
  checkUpdate: async (): Promise<UpdateStatus> => (inTauri ? invoke("check_update") : { state: "unavailable", reason: "updates only work inside the PowerCost app" }),
  /** Runs the update script: PowerCost quits, rebuilds, installs over itself and restarts. */
  startUpdate: async (): Promise<void> => {
    if (inTauri) return invoke("start_update");
    throw PREVIEW_ONLY;
  },

  getSettings: async (): Promise<Settings> => (inTauri ? invoke("get_settings") : previewLoad()),

  /** Resolves with the saved settings, rejects with a list of problems. */
  saveSettings: async (settings: Settings): Promise<Settings> => {
    if (inTauri) return invoke("save_settings", { settings });
    try {
      localStorage.setItem(PREVIEW_SETTINGS_KEY, JSON.stringify(settings));
    } catch {
      /* preview only */
    }
    return settings;
  },

  listTariffs: async (): Promise<TariffList> => (inTauri ? invoke("list_tariffs") : mock("tariffs.json")),
  getTariff: async (id: string, version: number): Promise<unknown> => (inTauri ? invoke("get_tariff", { id, version }) : mock(`tariff-${id}-${version}.json`)),
  validateTariff: async (json: unknown): Promise<ValidationReport> =>
    inTauri ? invoke("validate_tariff", { json }) : { ok: true, errors: [], warnings: [], prices: [] },
  saveTariff: async (json: unknown, recomputeFrom: string | null): Promise<SaveTariffResult> => {
    if (inTauri) return invoke("save_tariff", { json, recomputeFrom });
    throw PREVIEW_ONLY;
  },
  deleteTariff: async (id: string, version: number): Promise<void> => {
    if (inTauri) return invoke("delete_tariff", { id, version });
    throw PREVIEW_ONLY;
  },
  detectRegion: async (locale: string, timezone: string): Promise<RegionInfo> => {
    if (inTauri) return invoke("detect_region", { locale, timezone });
    const list: TariffList = await mock("tariffs.json");
    const country = timezone === "Europe/Sofia" || locale.endsWith("BG") ? "BG" : (locale.split("-")[1] ?? "").toUpperCase();
    return { candidates: country ? [{ country, source: "timezone" }] : [], suggestions: list.presets.filter((p) => p.country === country) };
  },
  presetsForCountry: async (country: string): Promise<PresetInfo[]> => {
    if (inTauri) return invoke("presets_for_country", { country });
    return ((await mock("tariffs.json")) as TariffList).presets.filter((p) => p.country === country);
  },
  saveCalibration: async (points: CalibrationPoint[] | null, days: number): Promise<Reestimate> => {
    if (inTauri) return invoke("save_calibration", { points, days });
    const s = previewLoad();
    s.estimator.calibration = points ? { points } : null;
    await api.saveSettings(s);
    return { spans: 0, clipped_by_compaction: false };
  },
  repriceHistory: async (days: number): Promise<number> => {
    if (inTauri) return invoke("reprice_history", { days });
    throw PREVIEW_ONLY;
  },
  exportData: async (req: ExportRequest): Promise<string> => {
    if (inTauri) return invoke("export_data", { ...req });
    throw PREVIEW_ONLY;
  },
  testNotification: async (): Promise<void> => {
    if (inTauri) return invoke("send_test_notification");
    throw PREVIEW_ONLY;
  },
  stopwatchStart: async (label: string): Promise<void> => {
    if (inTauri) {
      await invoke("stopwatch_start", { label });
      return;
    }
    previewStopwatch.start(label);
  },
  stopwatchStatus: async (): Promise<StopwatchStatus> => (inTauri ? invoke("stopwatch_status") : previewStopwatch.status()),
  stopwatchStop: async (): Promise<StopwatchSession> => (inTauri ? invoke("stopwatch_stop") : previewStopwatch.stop()),
  stopwatchCancel: async (): Promise<void> => {
    if (inTauri) return invoke("stopwatch_cancel");
    previewStopwatch.cancel();
  },
  stopwatchHistory: async (): Promise<StopwatchSession[]> => (inTauri ? invoke("stopwatch_history") : previewStopwatch.history()),
  stopwatchDelete: async (id: string): Promise<void> => {
    if (inTauri) return invoke("stopwatch_delete", { id });
    previewStopwatch.remove(id);
  },
  /** System "save as" dialog (app only). */
  pickSavePath: async (defaultName: string, ext: "csv" | "json"): Promise<string | null> => {
    if (!inTauri) return null;
    const { save } = await import("@tauri-apps/plugin-dialog");
    return save({ defaultPath: defaultName, filters: [{ name: ext.toUpperCase(), extensions: [ext] }] });
  },
};